type RouteMap = Record<string, string>

const routes: RouteMap = {
  "/orders": "http://orders-service",
  "/products": "http://catalog-service"
}

export function resolveTarget(path: string): string | null {
  const entry = Object.entries(routes).find(([prefix]) => path.startsWith(prefix))
  return entry ? entry[1] : null
}

type State = "closed" | "open" | "half-open"

export function nextCircuitState(failures: number, threshold: number): State {
  if (failures >= threshold) return "open"
  return "closed"
}
